import{_ as t,o as s,c as i,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Loi sur la Protection des Consommateurs","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0042-消费者保护法.md","filePath":"fr/0042-消费者保护法.md"}'),r={name:"fr/0042-消费者保护法.md"};function n(a,e,d,l,u,c){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="loi-sur-la-protection-des-consommateurs" tabindex="-1">Loi sur la Protection des Consommateurs <a class="header-anchor" href="#loi-sur-la-protection-des-consommateurs" aria-label="Permalink to &quot;Loi sur la Protection des Consommateurs&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>42</td></tr><tr><td>Module</td><td>Système Juridique et Cadre de Gouvernance</td></tr><tr><td>Mots clés</td><td>Droits des consommateurs, Commerce équitable, Anti-fraude, Responsabilité du produit, Marché symbiotique</td></tr></tbody></table><h2 id="i-objectif-legislatif-et-champ-d-application" tabindex="-1">I. Objectif Législatif et Champ d&#39;Application <a class="header-anchor" href="#i-objectif-legislatif-et-champ-d-application" aria-label="Permalink to &quot;I. Objectif Législatif et Champ d&#39;Application&quot;">​</a></h2><p>La <em>Loi sur la Protection des Consommateurs</em> est l&#39;une des lois fondamentales du système juridique de la Civilisation Symbiotique de l&#39;Ancre. Avec la <em>Loi Symbiotique du Travail</em>, elle constitue les deux piliers de la vie économique. Cette Loi vise à protéger les droits et intérêts légitimes de tous les consommateurs au sein de l&#39;Univers Hengyuan, à réglementer les comportements de transaction sur le marché, à maintenir un ordre de marché équitable, honnête et symbiotique, et à empêcher les pratiques commerciales prédatrices de porter atteinte aux droits et intérêts des êtres.</p><p>Cette Loi s&#39;applique à tous les consommateurs au sein de l&#39;Univers Hengyuan qui achètent ou utilisent des biens ou reçoivent des services pour satisfaire des besoins de vie personnels ou familiaux, ainsi qu&#39;aux opérateurs économiques qui fournissent des biens ou services aux consommateurs. Les transactions interplans sont également soumises à cette Loi, mais des règles d&#39;application peuvent être élaborées selon les différences entre plans.</p><h2 id="ii-droits-fondamentaux-des-consommateurs" tabindex="-1">II. Droits Fondamentaux des Consommateurs <a class="header-anchor" href="#ii-droits-fondamentaux-des-consommateurs" aria-label="Permalink to &quot;II. Droits Fondamentaux des Consommateurs&quot;">​</a></h2><p>Cette Loi établit que les consommateurs jouissent des neuf droits fondamentaux suivants :</p><table tabindex="0"><thead><tr><th>Droit</th><th>Contenu</th></tr></thead><tbody><tr><td>Droit à la garantie de sécurité</td><td>Les consommateurs jouissent du droit de ne pas voir leur sécurité personnelle et leurs biens endommagés lors de l&#39;achat ou de l&#39;utilisation de biens et de la réception de services</td></tr><tr><td>Droit de connaître la vérité</td><td>Les consommateurs ont le droit de connaître la situation réelle des biens achetés ou utilisés ou des services reçus, y compris la composition, l&#39;efficacité, les risques, etc.</td></tr><tr><td>Droit au choix autonome</td><td>Les consommateurs ont le droit de choisir librement des biens ou services, de comparer, d&#39;identifier et de sélectionner, et de refuser les transactions forcées</td></tr><tr><td>Droit à une transaction équitable</td><td>Les consommateurs ont le droit d&#39;obtenir des conditions de transaction équitables telles que la garantie de qualité, des prix raisonnables et une mesure exacte</td></tr><tr><td>Droit d&#39;indemnisation légale</td><td>Les consommateurs qui subissent des dommages personnels ou matériels en achetant ou utilisant des biens ou recevant des services jouissent du droit d&#39;obtenir une indemnisation conformément à la loi</td></tr><tr><td>Droit d&#39;association pour la défense des droits</td><td>Les consommateurs ont le droit de constituer ou de rejoindre des organisations de consommateurs conformément à la loi pour défendre leurs droits et intérêts légitimes</td></tr><tr><td>Droit d&#39;obtenir des connaissances</td><td>Les consommateurs ont le droit d&#39;obtenir des connaissances et des informations sur la consommation et la protection des droits des consommateurs</td></tr><tr><td>Droit au respect</td><td>Lors de l&#39;achat ou de l&#39;utilisation de biens et de la réception de services, les consommateurs jouissent du droit de voir leur dignité personnelle et leurs coutumes ethniques respectées</td></tr><tr><td>Droit de supervision</td><td>Les consommateurs ont le droit de superviser les biens et services ainsi que le travail de protection des droits des consommateurs, et de formuler des critiques et des suggestions</td></tr></tbody></table><h2 id="iii-obligations-des-operateurs-economiques" tabindex="-1">III. Obligations des Opérateurs Économiques <a class="header-anchor" href="#iii-obligations-des-operateurs-economiques" aria-label="Permalink to &quot;III. Obligations des Opérateurs Économiques&quot;">​</a></h2><p>Lorsqu&#39;ils fournissent des biens ou services aux consommateurs, les opérateurs économiques doivent remplir les obligations suivantes :</p><ol><li><strong>Obligation d&#39;exploitation licite</strong> : les opérateurs doivent respecter la Constitution et les lois et exercer leurs activités dans le cadre de leur périmètre agréé.</li><li><strong>Obligation de garantie de sécurité</strong> : les opérateurs doivent garantir que les biens ou services fournis satisfont aux exigences de protection de la sécurité personnelle et matérielle, et fournir des explications véridiques et des avertissements clairs pour les biens et services susceptibles de mettre en danger la sécurité.</li><li><strong>Obligation d&#39;information véridique</strong> : les opérateurs doivent fournir aux consommateurs des informations véridiques sur les biens ou services, et ne doivent pas faire de publicité fausse ou trompeuse. Les biens et services de type culture doivent indiquer fidèlement les limites d&#39;efficacité et les risques potentiels.</li><li><strong>Obligation de garantie de qualité</strong> : les opérateurs doivent garantir que, dans des conditions normales d&#39;utilisation des biens ou de réception des services, les biens ou services fournis ont la qualité, les performances, l&#39;usage et la durée de validité qu&#39;ils doivent avoir.</li><li><strong>Obligation de transaction équitable</strong> : les opérateurs ne doivent pas, par des clauses types, des notifications, des déclarations, des avis en magasin ou d&#39;autres moyens, établir des dispositions injustes ou déraisonnables excluant ou limitant les droits des consommateurs, réduisant ou exonérant la responsabilité de l&#39;opérateur, ou aggravant la responsabilité du consommateur.</li><li><strong>Obligation de service après-vente</strong> : les opérateurs doivent, conformément aux réglementations nationales ou aux accords avec les consommateurs, assumer la responsabilité de réparation, de remplacement, de retour et d&#39;autres services après-vente.</li><li><strong>Obligation de protection de la vie privée</strong> : les opérateurs doivent protéger les informations personnelles et les données de conscience des consommateurs ; sans le consentement du consommateur, ils ne doivent pas les collecter, les utiliser ou les divulguer.</li></ol><h2 id="iv-reglement-des-litiges-et-responsabilite-juridique" tabindex="-1">IV. Règlement des Litiges et Responsabilité Juridique <a class="header-anchor" href="#iv-reglement-des-litiges-et-responsabilite-juridique" aria-label="Permalink to &quot;IV. Règlement des Litiges et Responsabilité Juridique&quot;">​</a></h2><p>En cas de litige relatif aux droits des consommateurs entre un consommateur et un opérateur, il peut être résolu par les voies suivantes :</p><ul><li>Négociation d&#39;un accord amiable avec l&#39;opérateur</li><li>Demande de médiation auprès d&#39;une organisation de consommateurs</li><li>Dépôt d&#39;une plainte auprès du service administratif compétent</li><li>Demande d&#39;arbitrage auprès d&#39;une institution d&#39;arbitrage conformément à la convention d&#39;arbitrage conclue avec l&#39;opérateur</li><li>Dépôt d&#39;une action devant le Tribunal Symbiotique</li></ul><p>Les opérateurs qui violent les dispositions de cette Loi et portent atteinte aux droits et intérêts légitimes des consommateurs doivent assumer les responsabilités suivantes :</p><table tabindex="0"><thead><tr><th>Acte illégal</th><th>Responsabilité juridique</th></tr></thead><tbody><tr><td>Fourniture de biens ou services défectueux causant un préjudice</td><td>Assumer la responsabilité d&#39;indemnisation, y compris les frais médicaux, l&#39;indemnité pour perte de travail, l&#39;indemnité d&#39;invalidité, etc.</td></tr><tr><td>Comportement frauduleux</td><td>Augmenter l&#39;indemnisation à la demande du consommateur, à hauteur de trois fois le prix des biens achetés ou le coût des services reçus</td></tr><tr><td>Publicité mensongère</td><td>Ordonner la cessation de l&#39;acte illégal, l&#39;élimination de l&#39;impact et le paiement d&#39;une amende</td></tr><tr><td>Transactions forcées</td><td>Ordonner la rectification, le remboursement des frais déraisonnables et le paiement d&#39;une amende</td></tr><tr><td>Atteinte à la vie privée du consommateur</td><td>Assumer l&#39;indemnisation du préjudice moral ; en cas de circonstances graves, poursuivre la responsabilité pénale</td></tr></tbody></table><h2 id="v-organisations-de-consommateurs-et-supervision-sociale" tabindex="-1">V. Organisations de Consommateurs et Supervision Sociale <a class="header-anchor" href="#v-organisations-de-consommateurs-et-supervision-sociale" aria-label="Permalink to &quot;V. Organisations de Consommateurs et Supervision Sociale&quot;">​</a></h2><p>L&#39;État encourage et soutient toutes les organisations et tous les individus dans la supervision sociale des actes portant atteinte aux droits et intérêts légitimes des consommateurs. L&#39;Association des Consommateurs est une organisation sociale légalement établie pour exercer une supervision sociale sur les biens et services et protéger les droits et intérêts légitimes des consommateurs, remplissant les fonctions suivantes :</p><ol><li>Fournir aux consommateurs des informations sur la consommation et des services de conseil</li><li>Participer à la supervision et à l&#39;inspection des biens et services par les services administratifs compétents</li><li>Refléter, interroger et faire des suggestions aux services administratifs compétents sur les questions relatives aux droits et intérêts légitimes des consommateurs</li><li>Recevoir les plaintes des consommateurs, enquêter et médier sur les objets des plaintes</li><li>Soutenir les consommateurs lésés dans l&#39;introduction d&#39;actions contre les actes portant atteinte aux droits et intérêts légitimes des consommateurs</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La <em>Loi sur la Protection des Consommateurs</em> est la gardienne de l&#39;ordre du marché de la Civilisation Symbiotique de l&#39;Ancre. En conférant aux consommateurs des droits complets, en encadrant le comportement des opérateurs et en établissant un mécanisme pluraliste de règlement des litiges, elle garantit que les transactions du marché s&#39;opèrent sur la voie de l&#39;équité, de l&#39;honnêteté et de la symbiose, empêchant la sphère commerciale de devenir un nouveau terreau de comportements prédateurs.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitution Symbiotique : Principes Généraux)</li><li>41-共生劳动法 (Loi Symbiotique du Travail)</li><li>47-反垄断法 (Loi Antimonopole)</li><li>36-社会结构与阶层流动 (Structure Sociale et Mobilité des Classes)</li></ul>',23)])])}const b=t(r,[["render",n]]);export{p as __pageData,b as default};
